use String;
use std::vec::Vec;

use crate::{CommonEnv, ShellCmdApi};
use zcashapp_api::ZcashAppClient;

// Test fixture: PCZT + sighash for the "abandon...about" test mnemonic, account 0.
// Generated by: cargo test -p zcashapp -- --ignored dump_test_fixture --nocapture
const TEST_MNEMONIC: &str = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const TEST_SIGHASH: [u8; 32] = hex_literal::hex!("a9e7b262d085bdb1a5a7dd78029c484182a0ee7cf9c03cfcccbca8a5acd00a13");
const TEST_PCZT: &[u8] = &hex_literal::hex!("");

pub struct Zec {
    client: Option<ZcashAppClient>,
}
impl Zec {
    pub fn new() -> Self { Zec { client: None } }

    fn client(&mut self) -> Result<&ZcashAppClient, xous::Error> {
        if self.client.is_none() {
            match ZcashAppClient::new() {
                Ok(c) => self.client = Some(c),
                Err(e) => {
                    log::error!("zec: failed to connect to zcashapp: {:?}", e);
                    return Err(xous::Error::InternalError);
                }
            }
        }
        Ok(self.client.as_ref().unwrap())
    }
}

impl<'a> ShellCmdApi<'a> for Zec {
    cmd_api!(zec);

    fn process(&mut self, args: String, _env: &mut CommonEnv) -> Result<Option<String>, xous::Error> {
        use core::fmt::Write;
        let mut ret = String::new();

        let helpstring = "zec [ping|config|address|fvk|status|mngenerate|clearseed|testsign|version]";

        let mut parts = args.split_whitespace();
        let cmd = parts.next().unwrap_or("").to_string();
        let args: Vec<String> = parts.map(|s| s.to_string()).collect();

        match cmd.as_str() {
            "version" => {
                // Embedded at compile time by services/bao-console/build.rs
                // (`git describe --long --abbrev=9 --tags --dirty --always`).
                write!(ret, "zec firmware: {}", env!("BAO_CONSOLE_VERSION")).unwrap();
            }
            "ping" => {
                let client = self.client()?;
                match client.ping() {
                    Ok(()) => write!(ret, "pong").unwrap(),
                    Err(e) => write!(ret, "ping failed: {:?}", e).unwrap(),
                }
            }
            "config" => {
                let client = self.client()?;
                match client.get_config() {
                    Ok((version, has_seed)) => {
                        write!(ret, "protocol={} has_seed={}", version, has_seed).unwrap();
                    }
                    Err(e) => write!(ret, "config failed: {:?}", e).unwrap(),
                }
            }
            "address" => {
                let account: u32 = args.first().and_then(|s| s.parse().ok()).unwrap_or(0);
                let client = self.client()?;
                match client.get_address(account) {
                    Ok(addr) => {
                        write!(ret, "account {} -> ", account).unwrap();
                        for b in &addr {
                            write!(ret, "{:02x}", b).unwrap();
                        }
                    }
                    Err(e) => write!(ret, "address failed: {:?}", e).unwrap(),
                }
            }
            "fvk" => {
                let account: u32 = args.first().and_then(|s| s.parse().ok()).unwrap_or(0);
                let client = self.client()?;
                match client.get_fvk(account) {
                    Ok(fvk) => {
                        write!(ret, "account {} -> ", account).unwrap();
                        for b in &fvk {
                            write!(ret, "{:02x}", b).unwrap();
                        }
                    }
                    Err(e) => write!(ret, "fvk failed: {:?}", e).unwrap(),
                }
            }
            "status" => {
                let client = self.client()?;
                match client.get_status() {
                    Ok(ready) => {
                        write!(ret, "ready={}", ready).unwrap();
                    }
                    Err(e) => write!(ret, "status failed: {:?}", e).unwrap(),
                }
            }
            "mngenerate" => {
                let client = self.client()?;
                match client.generate_mnemonic() {
                    Ok(()) => {
                        write!(ret, "mnemonic generated").unwrap();
                        if let Ok(addr) = client.get_address(0) {
                            ret.push_str("\naddress[0]: ");
                            for b in &addr {
                                write!(ret, "{:02x}", b).unwrap();
                            }
                        }
                    }
                    Err(e) => write!(ret, "mngenerate failed: {:?}", e).unwrap(),
                }
            }
            "clearseed" => {
                let client = self.client()?;
                match client.clear_seed() {
                    Ok(()) => write!(ret, "seed cleared").unwrap(),
                    Err(e) => write!(ret, "clearseed failed: {:?}", e).unwrap(),
                }
            }
            "testsign" => {
                // End-to-end signing test using embedded PCZT fixture.
                // 1. Import test mnemonic
                write!(ret, "Importing test mnemonic...\n").unwrap();
                let client = self.client()?;
                match client.import_mnemonic(TEST_MNEMONIC) {
                    Ok(()) => write!(ret, "  mnemonic imported\n").unwrap(),
                    Err(e) => {
                        write!(ret, "  import failed: {:?}", e).unwrap();
                        return Ok(Some(ret));
                    }
                }

                // 2. Verify address
                match client.get_address(0) {
                    Ok(addr) => {
                        write!(ret, "  address: ").unwrap();
                        for b in &addr[..8] { write!(ret, "{:02x}", b).unwrap(); }
                        write!(ret, "...\n").unwrap();
                    }
                    Err(e) => {
                        write!(ret, "  get_address failed: {:?}\n", e).unwrap();
                    }
                }

                // 3. Parse PCZT (just test that parse doesn't crash)
                write!(ret, "Calling sign_pczt ({} byte PCZT)...\n", TEST_PCZT.len()).unwrap();

                let sighash: [u8; 32] = TEST_SIGHASH;
                match client.sign_pczt(0, &sighash, &TEST_PCZT) {
                    Ok(signed) => {
                        write!(ret, "  SIGNED! {} bytes returned", signed.len()).unwrap();
                    }
                    Err(e) => {
                        write!(ret, "  sign_pczt failed: {:?}", e).unwrap();
                    }
                }
            }
            _ => {
                write!(ret, "{}", helpstring).unwrap();
            }
        }

        Ok(Some(ret))
    }
}
